package mz.bam.seeky.android;
import android.os.*;import android.net.Uri;import android.text.InputType;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
final class ArchiveUi {
 static void extract(MainActivity a,Catalog.Entry entry){if(entry.name.toLowerCase(Locale.ROOT).endsWith(".rar")){a.dialog().setTitle("Arquivo RAR").setMessage("A extracção RAR nativa ainda não está disponível nesta edição. ZIP, 7z, TAR, GZ, BZ2 e XZ têm suporte integrado.").setPositiveButton("Abrir com outra aplicação",(d,w)->a.externalOpen(entry)).setNegativeButton("Fechar",null).show();return;}if(!ready(a))return;File initial=destination(a,entry);form(a,true,Collections.singletonList(entry),initial);}
 static void compress(MainActivity a,List<Catalog.Entry> entries){if(!ready(a))return;if(entries.isEmpty()){a.toast("Seleccione os ficheiros que vai compactar.");return;}form(a,false,new ArrayList<>(entries),destination(a,entries.get(0)));}
 static boolean ready(MainActivity a){if(a.busy){a.toast("Aguarde ou cancele a operação actual.");return false;}if(!StorageAccess.all(a)){a.requestGlobal();a.toast("Autorize o acesso aos ficheiros para escolher a pasta de destino.");return false;}return true;}
 static File destination(MainActivity a,Catalog.Entry e){File dir=a.browseFolder;if(dir==null)try{dir=StorageAccess.file(e).getParentFile();}catch(Exception ignored){}if(dir==null||!StorageAccess.allowed(a,dir))dir=new File(Environment.getExternalStorageDirectory(),"Download");if(!dir.isDirectory())dir=Environment.getExternalStorageDirectory();return dir;}
 static void form(MainActivity a,boolean extract,List<Catalog.Entry> entries,File initial){LinearLayout fields=a.column();final File[] folder={initial};EditText name=new EditText(a);String base=entries.size()==1?entries.get(0).name.replaceFirst("(?i)(\\.tar)?\\.(zip|rar|7z|tar|tgz|gz|bz2|tbz2|xz|txz)$",""):"Ficheiros";name.setSingleLine();name.setText(base+(extract?"":".zip"));fields.addView(a.label(extract?"Nova pasta":"Nome do ZIP",12,a.muted));fields.addView(name);TextView where=a.label(initial.getPath(),12,a.text);fields.addView(where);fields.addView(a.button("Escolher pasta de destino",()->chooseFolder(a,folder[0],selected->{folder[0]=selected;where.setText(selected.getPath());})));EditText password=new EditText(a);password.setSingleLine();password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);if(extract&&entries.get(0).name.toLowerCase(Locale.ROOT).endsWith(".7z")){fields.addView(a.label("Palavra-passe 7z · opcional",12,a.muted));fields.addView(password);}a.dialog().setTitle(extract?"Extrair arquivo":"Compactar em ZIP").setView(fields).setMessage(extract?"Cria uma pasta nova no destino escolhido. Os ficheiros existentes são conservados.":entries.size()+" origens seleccionadas. Os ficheiros originais são conservados.").setPositiveButton(extract?"Extrair":"Compactar",(d,w)->{String value=name.getText().toString().trim();if(!Rules.validName(value)){a.toast("Escolha um nome sem barras nem campos vazios.");return;}if(!extract&&!value.toLowerCase(Locale.ROOT).endsWith(".zip"))value+=".zip";if(!StorageAccess.allowed(a,folder[0])){a.toast("Pasta sem acesso autorizado.");return;}run(a,extract,entries,folder[0],value,password.getText().toString().toCharArray());}).setNegativeButton("Cancelar",null).show();}
 interface Chosen{void use(File folder);}
 static void chooseFolder(MainActivity a,File dir,Chosen callback){a.finder.execute(()->{File[] children=dir.listFiles(File::isDirectory);List<File> dirs=new ArrayList<>();if(children!=null)for(File f:children)if(StorageAccess.allowed(a,f)&&!f.getName().startsWith("."))dirs.add(f);dirs.sort(Comparator.comparing(f->f.getName().toLowerCase(Locale.ROOT)));List<String> names=new ArrayList<>();List<File> targets=new ArrayList<>();File parent=dir.getParentFile();if(parent!=null&&StorageAccess.allowed(a,parent)){names.add("↑ Pasta anterior");targets.add(parent);}for(File f:dirs){if(names.size()>=300)break;names.add(f.getName());targets.add(f);}for(File root:StorageAccess.volumes(a))if(!root.equals(dir)){names.add("Armazenamento · "+StorageAccess.location(root));targets.add(root);}a.ui(()->a.dialog().setTitle("Pasta de destino").setMessage(dir.getPath()).setItems(names.toArray(new String[0]),(d,n)->chooseFolder(a,targets.get(n),callback)).setPositiveButton("Usar esta pasta",(d,w)->callback.use(dir)).setNegativeButton("Cancelar",null).show());});}
 static void run(MainActivity a,boolean extract,List<Catalog.Entry> entries,File folder,String name,char[] password){if(a.busy)return;a.startWork();CancellationSignal token=a.cancel;a.worker.execute(()->{File temp=null;try{List<File> sources=new ArrayList<>();ArchiveFiles.Work preparation=new ArchiveFiles.Work(()->a.dead||token.isCanceled(),(n,b,c)->a.report("A preparar arquivo · "+Rules.bytes(b)));for(Catalog.Entry e:entries){Uri uri=Uri.parse(e.uri);if("file".equals(uri.getScheme())){File source=StorageAccess.file(e);if(!StorageAccess.allowed(a,source))throw new IOException("Origem sem acesso autorizado: "+e.name);sources.add(source);}else{if(!"content".equals(uri.getScheme()))throw new IOException("Localização de origem inválida.");if(temp==null){temp=new File(a.getCacheDir(),"archive-"+UUID.randomUUID());if(!temp.mkdir())throw new IOException("Sem espaço para preparar o arquivo.");}File cached=new File(temp,new File(e.name).getName());if(cached.exists())throw new IOException("Duas origens têm o mesmo nome.");try(InputStream in=a.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(cached)){if(in==null)throw new IOException("Ficheiro indisponível.");preparation.copy(in,out,e.name);}sources.add(cached);}}ArchiveFiles.Progress progress=(n,b,c)->a.report((extract?"A extrair":"A compactar")+" · "+c+" entradas · "+Rules.bytes(b)+"\n"+n);File result=extract?ArchiveFiles.extract(sources.get(0),folder,name,password,()->a.dead||token.isCanceled(),progress):ArchiveFiles.compress(sources,folder,name,()->a.dead||token.isCanceled(),progress);a.record(extract?"Arquivo extraído":"ZIP criado",result.getName(),result.getPath());MediaUpdates.changed(a,result);CatalogEvents.publish("Arquivo concluído");a.ui(()->{a.selected.clear();a.dialog().setTitle(extract?"Extracção concluída":"ZIP criado").setMessage(result.getPath()).setPositiveButton("Abrir pasta",(d,w)->a.openFolder(extract?result:folder)).setNegativeButton("Fechar",null).show();});}catch(InterruptedIOException|OperationCanceledException error){a.ui(()->a.toast("Operação cancelada. As origens foram conservadas."));}catch(Exception|OutOfMemoryError error){a.ui(()->a.showError(error instanceof Exception?(Exception)error:new IOException("Memória insuficiente para este arquivo.",error)));}finally{Arrays.fill(password,'\0');if(temp!=null)ArchiveFiles.remove(temp);a.endWork();}});}
}
